  function apply(){const state={collection,coast,q:$('#search').value,...Object.fromEntries(keys.map(k=>[k,$('#'+k).value])),sort:$('#sort').value};filtered=customMode?myCrate.ids.map(id=>songs.find(s=>s.id===id)).filter(s=>s&&(!state.q||norm([s.title,s.artist,...s.samples.map(x=>x.title+' '+x.artist)].join(' ')).includes(norm(state.q)))):window.CrateFilter(songs,state);if(!started){queue=playableIds(filtered);if(queue.length)loadSong(songs.findIndex(x=>x.id===queue[0]),false)}resultPage=1;expandedCount=50;paintResults();$('#count').textContent=filtered.length+' / '+songs.length+' RECORDS';view.querySelectorAll('[data-crate]').forEach(b=>{const n=window.CrateFilter(songs,{...state,collection:b.dataset.crate}).length;b.querySelector('[data-shelf-count]').textContent=n+'曲';b.disabled=n===0&&b.dataset.crate!==collection&&b.dataset.crate!=='all'});$('#play-filter').disabled=!playableIds(filtered).length;$('#play-filter').textContent=customMode?'この選曲で連続再生 ▶':'この条件で連続再生 ▶';$('#my-crate-settings').hidden=!customMode;$('#library-tab').setAttribute('aria-pressed',String(!customMode));$('#my-crate-tab').setAttribute('aria-pressed',String(customMode));for(const sel of ['.crate-choices','.crate-current','.advanced-filters','.crate-sort'])$(sel).hidden=customMode;const params=new URLSearchParams();Object.entries(state).forEach(([k,v])=>{if(v&&!(k==='sort'&&v==='year')&&!((k==='collection'||k==='coast')&&v==='all'))params.set(k,v)});history.replaceState(null,'',params.size?'#/?'+params.toString():listBase);$('#hero').hidden=params.size>0||listBase==='#/songs';view.querySelectorAll('[data-crate]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.crate===collection)));view.querySelectorAll('[data-coast]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.coast===coast)));const chosen=scenes.find(x=>x[0]===collection);$('#crate-caption').textContent=chosen[2]+(coast==='all'?'':' · '+coasts.find(x=>x[0]===coast)[1]);$('#clear-browse').disabled=collection==='all'&&coast==='all'&&!state.q&&!keys.some(k=>state[k])&&state.sort==='year';}
