 function sourceBlock(s){const sample=s.samples.find(x=>x.main),y=sample?.youtube;return sample?'<div class="main-sample"><span class="eyebrow">THE MAIN SAMPLE</span><h3>'+esc(sample.title)+'</h3><p>'+esc(sample.artist)+' / '+(sample.year||'年未確認')+'</p><p>'+esc(sample.role)+'</p>'+(y?'<div class="sample-video"><div id="sample-yt"></div></div><div class="sample-actions"><button id="sample-start">サンプル元を聴く ▶</button><button id="sample-return">この曲へ戻る ↩</button></div><small>'+esc(y.channel)+' / '+(y.official===false?'参考投稿':'公式配信')+'</small><a href="https://www.youtube.com/watch?v='+y.id+'" target="_blank" rel="noopener">YouTubeで開く ↗</a>':'<p>適切なYouTube音源は未確認のため、再生欄を省略しています。</p>')+refs(s,sample.sources)+'</div>':'<p class="read-only-note">'+esc(s.samples.length?'資料でたどれるサンプルを以下に掲載しています。':(s.sampleStatus||'サンプル関係は個別調査中です。'))+'</p>'}
